 * The ONE "Workspace Limit Reached" 400 page (LIN-3125 Phase 3). Shared by the
 * credentials-mode GitHub new-container arm (`lib/github-install-flow.js`) and
 * the held `mode=new` picker arm (`routes/held-connection.js`) so the two sites
 * cannot drift in title, message or action.
 * @returns {string} Full HTML document
 */
export const WORKSPACE_LIMIT_TITLE = 'Workspace Limit Reached';
export const WORKSPACE_LIMIT_MESSAGE = 'You have reached the maximum number of connected workspaces. Please remove one before adding another.';
export function renderWorkspaceLimitPage() {
  return renderErrorPage(WORKSPACE_LIMIT_TITLE, WORKSPACE_LIMIT_MESSAGE, { action: 'Go to dashboard', actionUrl: '/' });
}

export const SERVICE_UNAVAILABLE_TITLE = 'Service Unavailable';
export const SERVICE_UNAVAILABLE_MESSAGE = 'Service temporarily unavailable. Please try again later.';
/** The ONE 503 page (LIN-3466): delegates to renderErrorPage, not a second writer. */
export function renderServiceUnavailablePage() {
  return renderErrorPage(SERVICE_UNAVAILABLE_TITLE, SERVICE_UNAVAILABLE_MESSAGE);
}

